@Slf4j
@PluginDescriptor(
	name = "Merch Lens",
	description = "Passive Grand Exchange market research for OSRS flipping.",
	tags = {"grand exchange", "flipping", "merching", "profit", "prices"}
)
public class MerchLensPlugin extends Plugin
{
	private static final String MENU_OPTION_MERCH = "Merch";
	private static final int SCREENER_TREND_BATCH_SIZE = 18;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Client client;

	@Inject
	private MerchLensConfig config;

	@Inject
	private WikiMarketClient wikiMarketClient;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TooltipManager tooltipManager;

	private OfferTracker offerTracker;
	private FlipLogStore flipLogStore;
	private GeOfferOverlay geOfferOverlay;
	private FavoriteItemStore favoriteItemStore;
	private MerchLensPanel panel;
	private NavigationButton navigationButton;
	private volatile long refreshSequence;
	private volatile long chartSequence;
	private final Set<Integer> visibleTrendWarmInFlight = Collections.synchronizedSet(new HashSet<>());
	private final Object screenerTrendScanLock = new Object();
	private volatile long screenerTrendScanSequence;
	private String runningScreenerTrendScanKey;
	private String completedScreenerTrendScanKey;

	@Provides
	MerchLensConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MerchLensConfig.class);
	}

	@Override
	protected void startUp()
	{
		offerTracker = new OfferTracker(configManager, gson);
		offerTracker.load();
		flipLogStore = new FlipLogStore(configManager, gson);
		flipLogStore.load();
		geOfferOverlay = new GeOfferOverlay(offerTracker, itemManager, config, client, tooltipManager);
		overlayManager.add(geOfferOverlay);
		favoriteItemStore = new FavoriteItemStore(configManager, gson);
		favoriteItemStore.load();
		panel = new MerchLensPanel(
			this::refreshRecommendations,
			this::searchItem,
			this::toggleFavorite,
			this::showChart,
			this::warmVisibleTrendSignals,
			this::scanScreenerTrends,
			this::cancelScreenerTrendScan,
			this::resetFlipLog,
			this::updateControlsCollapsed,
			config.controlsCollapsed(),
			this::updateGeOfferOverlayVisible,
			config.showGeOfferOverlay(),
			this::updateScreenerFilters,
			config.screenerMinPrice(),
			config.screenerMaxPrice(),
			config.screenerMinBuyVolume(),
			config.screenerMinSellVolume(),
			config.screenerBuySellRatio(),
			itemManager
		);
		panel.setFlipLogRecords(flipLogStore.records());
		BufferedImage icon = createFallbackIcon();
		navigationButton = NavigationButton.builder()
			.tooltip("Merch Lens")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
		loadSearchIndex();
		refreshRecommendations();
	}

	@Override
	protected void shutDown()
	{
		cancelScreenerTrendScan();
		if (geOfferOverlay != null)
		{
			overlayManager.remove(geOfferOverlay);
		}
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
		}
		favoriteItemStore = null;
		flipLogStore = null;
		offerTracker = null;
		geOfferOverlay = null;
		panel = null;
		navigationButton = null;
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (event == null || event.getOffer() == null)
		{
			return;
		}
		if (offerTracker == null)
		{
			return;
		}
		if (event.getOffer().getState() == GrandExchangeOfferState.EMPTY && client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		OfferFill fill = offerTracker.record(event.getSlot(), event.getOffer());
		if (fill != null && flipLogStore != null)
		{
			ItemComposition item = itemManager.getItemComposition(fill.getItemId());
			String itemName = item == null ? null : item.getName();
			flipLogStore.record(fill, itemName);
			MerchLensPanel currentPanel = panel;
			if (currentPanel != null)
			{
				currentPanel.setFlipLogRecords(flipLogStore.records());
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event == null || !"merchlens".equals(event.getGroup()) || !"showGeOfferOverlay".equals(event.getKey()))
		{
			return;
		}
		MerchLensPanel currentPanel = panel;
		if (currentPanel != null)
		{
			currentPanel.setGeOfferOverlayVisible(config.showGeOfferOverlay());
		}
	}

	@Subscribe
	@SuppressWarnings("deprecation")
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.showItemMenuLookup() || event == null || event.getMenuEntry() == null)
		{
			return;
		}

		MenuAction type = event.getMenuEntry().getType();
		boolean widgetItemExamine = type == MenuAction.CC_OP_LOW_PRIORITY && "Examine".equals(event.getOption());
		if (type != MenuAction.EXAMINE_ITEM && type != MenuAction.EXAMINE_ITEM_GROUND && !widgetItemExamine)
		{
			return;
		}
		if (widgetItemExamine)
		{
			String lookupName = plainMenuTarget(event.getTarget());
			if (lookupName.isEmpty())
			{
				return;
			}
			client.getMenu().createMenuEntry(-1)
				.setOption(MENU_OPTION_MERCH)
				.setTarget(event.getTarget())
				.setType(MenuAction.RUNELITE)
				.onClick(entry -> openLookupFromMenu(lookupName));
			return;
		}

		int itemId = type == MenuAction.EXAMINE_ITEM_GROUND ? event.getIdentifier() : event.getItemId();
		if (itemId <= 0 && event.getMenuEntry().getWidget() != null)
		{
			itemId = event.getMenuEntry().getWidget().getItemId();
		}
		if (itemId <= 0)
		{
			itemId = event.getIdentifier();
		}
		itemId = itemManager.canonicalize(itemId);
		if (itemId <= 0)
		{
			return;
		}

		ItemComposition composition = itemManager.getItemComposition(itemId);
		if (composition == null || composition.getName() == null || composition.getName().trim().isEmpty())
		{
			return;
		}

		int lookupItemId = itemId;
		String lookupName = composition.getName();
		client.getMenu().createMenuEntry(-1)
			.setOption(MENU_OPTION_MERCH)
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(entry -> openLookupFromMenu(lookupItemId, lookupName));
	}

	private String plainMenuTarget(String target)
	{
		return target == null ? "" : target.replaceAll("<[^>]+>", "").trim();
	}

	private void openLookupFromMenu(int itemId, String itemName)
	{
		SwingUtilities.invokeLater(() -> {
			MerchLensPanel currentPanel = panel;
			if (currentPanel == null || navigationButton == null)
			{
				return;
			}
			clientToolbar.openPanel(navigationButton);
			currentPanel.lookupItem(itemId, itemName);
		});
	}

	private void openLookupFromMenu(String itemName)
	{
		SwingUtilities.invokeLater(() -> {
			MerchLensPanel currentPanel = panel;
			if (currentPanel == null || navigationButton == null)
			{
				return;
			}
			clientToolbar.openPanel(navigationButton);
			currentPanel.lookupItem(itemName);
		});
	}

	private void refreshRecommendations()
	{
		MerchLensPanel currentPanel = panel;
		if (currentPanel == null)
		{
			return;
		}

		cancelScreenerTrendScan();
		currentPanel.showLoading();
		long sequence = ++refreshSequence;
		// Network work stays off the client thread. The result is marshalled back through Swing in the panel.
		Thread worker = new Thread(() -> {
			try
			{
				SignalResponse response = loadSignals();
				if (!isCurrentRefresh(sequence, currentPanel))
				{
					return;
				}
				currentPanel.showRecommendations(response);
				warmHistoryAndRefresh(sequence, currentPanel, response);
			}
			catch (Exception ex)
			{
				log.debug("Unable to refresh Merch Lens recommendations", ex);
				if (isCurrentRefresh(sequence, currentPanel))
				{
					currentPanel.showError("Market data unavailable: " + ex.getMessage());
				}
			}
		}, "merch-lens-refresh");
		worker.setDaemon(true);
		worker.start();
	}

	private SignalResponse loadSignals() throws Exception
	{
		return wikiMarketClient.getMarketSignals(
			config,
			favoriteItemStore == null ? java.util.Collections.emptySet() : favoriteItemStore.itemIds()
		);
	}

	private void warmHistoryAndRefresh(long sequence, MerchLensPanel currentPanel, SignalResponse response)
	{
		try
		{
			int warmed = wikiMarketClient.warmHistoricalSignals(response.getHighVolumeRecommendations(), response.getRecommendations(), response.getFavoriteRecommendations());
			if (warmed <= 0 || !isCurrentRefresh(sequence, currentPanel))
			{
				return;
			}
			SignalResponse refreshed = loadSignals();
			if (isCurrentRefresh(sequence, currentPanel))
			{
				currentPanel.showRecommendations(refreshed);
			}
		}
		catch (Exception ex)
		{
			log.debug("Unable to warm Merch Lens trend data", ex);
		}
	}

	private void warmVisibleTrendSignals(List<RecommendationDto> recommendations)
	{
		MerchLensPanel currentPanel = panel;
		if (currentPanel == null || recommendations == null || recommendations.isEmpty())
		{
			return;
		}

		List<RecommendationDto> toWarm = new ArrayList<>();
		for (RecommendationDto recommendation : recommendations)
		{
			if (recommendation == null || recommendation.getItemId() <= 0)
			{
				continue;
			}
			if (visibleTrendWarmInFlight.add(recommendation.getItemId()))
			{
				toWarm.add(recommendation);
			}
		}
		if (toWarm.isEmpty())
		{
			return;
		}

		long sequence = refreshSequence;
		Thread worker = new Thread(() -> {
			try
			{
				int warmed = wikiMarketClient.warmHistoricalSignals(toWarm);
				if (warmed > 0 && isCurrentRefresh(sequence, currentPanel))
				{
					currentPanel.showRecommendations(loadSignals());
				}
			}
			catch (Exception ex)
			{
				log.debug("Unable to warm visible Merch Lens trend data", ex);
			}
			finally
			{
				for (RecommendationDto recommendation : toWarm)
				{
					visibleTrendWarmInFlight.remove(recommendation.getItemId());
				}
			}
		}, "merch-lens-visible-trends");
		worker.setDaemon(true);
		worker.start();
	}

	private void scanScreenerTrends(List<RecommendationDto> recommendations)
	{
		MerchLensPanel currentPanel = panel;
		if (currentPanel == null || recommendations == null)
		{
			return;
		}

		List<RecommendationDto> candidates = new ArrayList<>(recommendations);
		String scanKey = screenerTrendScanKey(candidates);
		long scanSequence;
		synchronized (screenerTrendScanLock)
		{
			if (scanKey.equals(runningScreenerTrendScanKey))
			{
				return;
			}
			if (scanKey.equals(completedScreenerTrendScanKey))
			{
				currentPanel.showScreenerTrendProgress(candidates.size(), candidates.size(), true);
				return;
			}
			runningScreenerTrendScanKey = scanKey;
			scanSequence = ++screenerTrendScanSequence;
		}

		List<RecommendationDto> missing = new ArrayList<>();
		for (RecommendationDto recommendation : candidates)
		{
			if (recommendation != null && needsTrendScan(recommendation))
			{
				missing.add(recommendation);
			}
		}
		int checked = candidates.size() - missing.size();
		currentPanel.showScreenerTrendProgress(checked, candidates.size(), missing.isEmpty());
		if (missing.isEmpty())
		{
			completeScreenerTrendScan(scanSequence, scanKey);
			return;
		}

		long refreshAtStart = refreshSequence;
		Thread worker = new Thread(() -> {
			int completed = checked;
			try
			{
				for (int start = 0; start < missing.size(); start += SCREENER_TREND_BATCH_SIZE)
				{
					if (!isCurrentScreenerTrendScan(scanSequence, scanKey, refreshAtStart, currentPanel))
					{
						return;
					}
					int end = Math.min(start + SCREENER_TREND_BATCH_SIZE, missing.size());
					wikiMarketClient.warmHistoricalSignals(new ArrayList<>(missing.subList(start, end)));
					completed += end - start;
					if (isCurrentScreenerTrendScan(scanSequence, scanKey, refreshAtStart, currentPanel))
					{
						currentPanel.showScreenerTrendProgress(completed, candidates.size(), false);
					}
				}
				if (!isCurrentScreenerTrendScan(scanSequence, scanKey, refreshAtStart, currentPanel))
				{
					return;
				}
				SignalResponse refreshed = loadSignals();
				if (isCurrentScreenerTrendScan(scanSequence, scanKey, refreshAtStart, currentPanel))
				{
					completeScreenerTrendScan(scanSequence, scanKey);
					currentPanel.showRecommendations(refreshed);
					currentPanel.showScreenerTrendProgress(candidates.size(), candidates.size(), true);
				}
			}
			catch (Exception ex)
			{
				log.debug("Unable to complete Merch Lens Screener trend scan", ex);
			}
		}, "merch-lens-screener-trends");
		worker.setDaemon(true);
		worker.start();
	}

	private boolean needsTrendScan(RecommendationDto recommendation)
	{
		return recommendation.getMarketState() == null || "UNKNOWN".equals(recommendation.getMarketState());
	}

	private String screenerTrendScanKey(List<RecommendationDto> recommendations)
	{
		List<Integer> itemIds = new ArrayList<>();
		for (RecommendationDto recommendation : recommendations)
		{
			if (recommendation != null)
			{
				itemIds.add(recommendation.getItemId());
			}
		}
		Collections.sort(itemIds);
		StringBuilder key = new StringBuilder();
		for (Integer itemId : itemIds)
		{
			key.append(itemId).append(',');
		}
		return key.toString();
	}

	private boolean isCurrentScreenerTrendScan(long scanSequence, String scanKey, long refreshAtStart, MerchLensPanel currentPanel)
	{
		synchronized (screenerTrendScanLock)
		{
			return panel == currentPanel
				&& refreshSequence == refreshAtStart
				&& screenerTrendScanSequence == scanSequence
				&& scanKey.equals(runningScreenerTrendScanKey);
		}
	}

	private void completeScreenerTrendScan(long scanSequence, String scanKey)
	{
		synchronized (screenerTrendScanLock)
		{
			if (screenerTrendScanSequence == scanSequence && scanKey.equals(runningScreenerTrendScanKey))
			{
				runningScreenerTrendScanKey = null;
				completedScreenerTrendScanKey = scanKey;
			}
		}
	}

	private void cancelScreenerTrendScan()
	{
		synchronized (screenerTrendScanLock)
		{
			screenerTrendScanSequence++;
			runningScreenerTrendScanKey = null;
			completedScreenerTrendScanKey = null;
		}
	}

	private boolean isCurrentRefresh(long sequence, MerchLensPanel currentPanel)
	{
		return sequence == refreshSequence && panel == currentPanel;
	}

	private void toggleFavorite(int itemId)
	{
		FavoriteItemStore currentStore = favoriteItemStore;
		if (currentStore != null)
		{
			currentStore.toggle(itemId);
			refreshRecommendations();
		}
	}

	private void updateControlsCollapsed(boolean collapsed)
	{
		configManager.setConfiguration("merchlens", "controlsCollapsed", collapsed);
	}

	private void updateGeOfferOverlayVisible(boolean visible)
	{
		configManager.setConfiguration("merchlens", "showGeOfferOverlay", visible);
	}

	private void resetFlipLog(long since)
	{
		if (flipLogStore == null)
		{
			return;
		}
		flipLogStore.clearCompletedSince(since);
		if (panel != null)
		{
			panel.setFlipLogRecords(flipLogStore.records());
		}
	}

	private void updateScreenerFilters(MerchLensPanel.ScreenerFilters filters)
	{
		if (filters == null)
		{
			return;
		}
		configManager.setConfiguration("merchlens", "screenerMinPrice", Math.max(0, filters.getMinPrice()));
		configManager.setConfiguration("merchlens", "screenerMaxPrice", Math.max(0, filters.getMaxPrice()));
		configManager.setConfiguration("merchlens", "screenerMinBuyVolume", Math.max(0, filters.getMinBuyVolume()));
		configManager.setConfiguration("merchlens", "screenerMinSellVolume", Math.max(0, filters.getMinSellVolume()));
		configManager.setConfiguration("merchlens", "screenerBuySellRatio", Math.max(0, filters.getBuySellRatio()));
	}

	private void searchItem(String query)
	{
		MerchLensPanel currentPanel = panel;
		if (currentPanel == null)
		{
			return;
		}
		currentPanel.showSearchLoading(query);
		Thread worker = new Thread(() -> {
			try
			{
				RecommendationDto recommendation = wikiMarketClient.searchItem(query, config);
				if (panel == currentPanel)
				{
					currentPanel.showSearchResult(recommendation);
				}
			}
			catch (Exception ex)
			{
				log.debug("Unable to search Merch Lens item", ex);
				if (panel == currentPanel)
				{
					currentPanel.showSearchError(ex.getMessage());
				}
			}
		}, "merch-lens-search");
		worker.setDaemon(true);
		worker.start();
	}

	private void showChart(RecommendationDto recommendation, MerchLensPanel.ChartPeriod period)
	{
		MerchLensPanel currentPanel = panel;
		if (currentPanel == null || recommendation == null || recommendation.getItemId() <= 0)
		{
			return;
		}
		long sequence = ++chartSequence;
		currentPanel.showChartLoading(recommendation, period);
		Thread worker = new Thread(() -> {
			try
			{
				List<TimeseriesPoint> points = period == MerchLensPanel.ChartPeriod.WEEKLY
					? wikiMarketClient.weeklyTimeseries(recommendation.getItemId())
					: wikiMarketClient.dailyTimeseries(recommendation.getItemId());
				if (panel == currentPanel && sequence == chartSequence)
				{
					currentPanel.showChart(recommendation, period, points);
				}
			}
			catch (Exception ex)
			{
				log.debug("Unable to load Merch Lens {} chart", period.label().toLowerCase(), ex);
				if (panel == currentPanel && sequence == chartSequence)
				{
					currentPanel.showChartError(recommendation, period, ex.getMessage());
				}
			}
		}, "merch-lens-" + period.label().toLowerCase() + "-chart");
		worker.setDaemon(true);
		worker.start();
	}

	private void loadSearchIndex()
	{
		MerchLensPanel currentPanel = panel;
		if (currentPanel == null)
		{
			return;
		}
		Thread worker = new Thread(() -> {
			try
			{
				List<ItemSearchResult> items = wikiMarketClient.searchIndex();
				if (panel == currentPanel)
				{
					currentPanel.setSearchItems(items);
				}
			}
			catch (Exception ex)
			{
				log.debug("Unable to load Merch Lens item search index", ex);
			}
		}, "merch-lens-search-index");
		worker.setDaemon(true);
		worker.start();
	}

	private BufferedImage createFallbackIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		drawToolbarCoin(graphics, 1, 10);
		drawToolbarCoin(graphics, 1, 6);
		drawToolbarCoin(graphics, 1, 2);
		graphics.dispose();
		return image;
	}

	private void drawToolbarCoin(Graphics2D graphics, int x, int y)
	{
		graphics.setColor(new Color(94, 56, 8));
		graphics.fillOval(x, y + 2, 14, 5);
		graphics.setColor(new Color(244, 185, 38));
		graphics.fillOval(x, y, 14, 5);
		graphics.setColor(new Color(112, 66, 10));
		graphics.setStroke(new BasicStroke(1f));
		graphics.drawOval(x, y, 14, 5);
		graphics.setColor(new Color(255, 230, 118));
		graphics.drawArc(x + 2, y + 1, 9, 3, 20, 120);
	}
}

package com.merchlens;

final class OfferFill
{
	enum Side
	{
		BUY,
		SELL
	}

	private final Side side;
	private final int itemId;
	private final int quantity;
	private final long totalValue;
	private final long filledAt;
	private final String offerKey;

	OfferFill(Side side, int itemId, int quantity, long totalValue, long filledAt)
	{
		this(side, itemId, quantity, totalValue, filledAt, side + ":" + itemId + ":" + filledAt);
	}

	OfferFill(Side side, int itemId, int quantity, long totalValue, long filledAt, String offerKey)
	{
		this.side = side;
		this.itemId = itemId;
		this.quantity = quantity;
		this.totalValue = totalValue;
		this.filledAt = filledAt;
		this.offerKey = offerKey;
	}

	Side getSide()
	{
		return side;
	}

	int getItemId()
	{
		return itemId;
	}

	int getQuantity()
	{
		return quantity;
	}

	long getTotalValue()
	{
		return totalValue;
	}

	long getFilledAt()
	{
		return filledAt;
	}

	String getOfferKey()
	{
		return offerKey;
	}
}

package com.merchlens;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.client.config.ConfigManager;

class OfferTracker
{
	private static final String GROUP = "merchlens";
	private static final String KEY = "trackedOffers";
	private static final long STARTUP_UNKNOWN_WINDOW_SECONDS = 20;
	private static final Type TRACKED_OFFERS_TYPE = new TypeToken<List<TrackedOffer>>() {}.getType();

	private final Map<Integer, TrackedOffer> activeOffers = new HashMap<>();
	private final ConfigManager configManager;
	private final Gson gson;
	private final long startedAt = Instant.now().getEpochSecond();

	OfferTracker(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	synchronized OfferFill record(int slot, GrandExchangeOffer offer)
	{
		if (offer == null || offer.getItemId() <= 0)
		{
			if (slot >= 0)
			{
				activeOffers.remove(slot);
				save();
			}
			return null;
		}
		long now = Instant.now().getEpochSecond();
		if (slot >= 0)
		{
			return recordActiveOffer(slot, offer, now);
		}
		return null;
	}

	synchronized List<TrackedOffer> activeOffers()
	{
		List<TrackedOffer> offers = new ArrayList<>();
		for (TrackedOffer offer : activeOffers.values())
		{
			if (offer != null && offer.isVisible())
			{
				offers.add(offer);
			}
		}
		offers.sort(Comparator.comparingInt(TrackedOffer::getSlot));
		return offers;
	}

	synchronized void load()
	{
		activeOffers.clear();
		if (configManager == null || gson == null)
		{
			return;
		}
		String json = configManager.getConfiguration(GROUP, KEY);
		if (json == null || json.trim().isEmpty())
		{
			return;
		}
		List<TrackedOffer> loaded = gson.fromJson(json, TRACKED_OFFERS_TYPE);
		if (loaded == null)
		{
			return;
		}
		for (TrackedOffer offer : loaded)
		{
			if (offer != null && offer.isVisible() && offer.getSlot() >= 0)
			{
				activeOffers.put(offer.getSlot(), offer);
			}
		}
	}

	private OfferFill recordActiveOffer(int slot, GrandExchangeOffer offer, long now)
	{
		String state = offer.getState() == null ? "EMPTY" : offer.getState().name();
		if ("EMPTY".equals(state) || offer.getItemId() <= 0 || offer.getTotalQuantity() <= 0)
		{
			activeOffers.remove(slot);
			save();
			return null;
		}

		TrackedOffer tracked = activeOffers.get(slot);
		boolean matchingOffer = tracked != null && tracked.matches(offer);
		int previousQuantity = matchingOffer ? tracked.getFilledQuantity() : 0;
		long previousSpent = matchingOffer ? tracked.getSpent() : 0L;
		boolean captureExistingProgress = matchingOffer;
		if (tracked != null && tracked.matches(offer))
		{
			tracked.update(offer, now);
		}
		else
		{
			boolean knownStart = now - startedAt > STARTUP_UNKNOWN_WINDOW_SECONDS;
			tracked = new TrackedOffer(slot, offer, now, knownStart);
			activeOffers.put(slot, tracked);
		}
		save();
		int filledQuantity = offer.getQuantitySold() - previousQuantity;
		long filledValue = offer.getSpent() - previousSpent;
		boolean captureNewOffer = !matchingOffer && tracked.isTrackedStartKnown();
		if (filledQuantity <= 0 || filledValue < 0 || (!captureExistingProgress && !captureNewOffer))
		{
			return null;
		}
		OfferFill.Side side = tracked.isBuyOffer() ? OfferFill.Side.BUY : OfferFill.Side.SELL;
		return new OfferFill(side, offer.getItemId(), filledQuantity, filledValue, now, tracked.offerKey());
	}

	private void save()
	{
		if (configManager != null && gson != null)
		{
			configManager.setConfiguration(GROUP, KEY, gson.toJson(activeOffers()));
		}
	}
}

package com.merchlens;

import com.merchlens.model.MarketItem;
import com.merchlens.model.RecommendationDto;
import com.merchlens.model.HistoricalSignal;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

class RecommendationEngine
{
	private static final int ACTIONABLE_PRICE_AGE_MINUTES = 10;
	private static final int MAX_STAPLE_PRICE_AGE_MINUTES = 60;
	private static final int STRATEGY_HOLD_WINDOW_HOURS = 12;
	private static final double STRATEGY_MINIMUM_ROI = 0.0025;
	private static final int SAFE_MIN_HOURLY_VOLUME = 250;
	private static final int HIGH_VOLUME_STAPLE_LIMIT = 350;

	List<RecommendationDto> screener(List<MarketItem> items, MerchLensConfig config)
	{
		return screener(items, config, new LinkedHashMap<>());
	}

	List<RecommendationDto> screener(List<MarketItem> items, MerchLensConfig config, Map<Integer, HistoricalSignal> history)
	{
		List<RecommendationDto> recommendations = new ArrayList<>();
		long now = System.currentTimeMillis() / 1000L;
		for (MarketItem item : items)
		{
			RecommendationDto recommendation = evaluateScreener(item, config, now, history.get(item.getMetadata().getId()));
			if (recommendation != null)
			{
				recommendations.add(recommendation);
			}
		}

		recommendations.sort(Comparator
			.comparingLong((RecommendationDto rec) -> Math.max(0L, rec.getFourHourFlowProfit())).reversed()
			.thenComparing(Comparator.comparingLong((RecommendationDto rec) -> Math.max(0L, (long) rec.getNetMargin() * rec.getBuyLimit())).reversed())
			.thenComparing(Comparator.comparingDouble(RecommendationDto::getRoi).reversed())
			.thenComparing(Comparator.comparingInt(RecommendationDto::getHourlyVolume).reversed()));
		return recommendations;
	}

	List<RecommendationDto> highVolumeStaples(List<MarketItem> items, MerchLensConfig config)
	{
		return highVolumeStaples(items, config, new LinkedHashMap<>());
	}

	List<RecommendationDto> highVolumeStaples(List<MarketItem> items, MerchLensConfig config, Map<Integer, HistoricalSignal> history)
	{
		List<RecommendationDto> recommendations = new ArrayList<>();
		long now = System.currentTimeMillis() / 1000L;
		for (MarketItem item : items)
		{
			if (!isHighVolumeStaple(item))
			{
				continue;
			}
			RecommendationDto recommendation = evaluateStaple(item, config, now, history.get(item.getMetadata().getId()));
			if (recommendation != null)
			{
				recommendations.add(recommendation);
			}
		}
		recommendations.sort(Comparator
			.comparing(RecommendationDto::getRoi, Comparator.reverseOrder())
			.thenComparing(RecommendationDto::getHourlyVolume, Comparator.reverseOrder()));
		return recommendations.subList(0, Math.min(HIGH_VOLUME_STAPLE_LIMIT, recommendations.size()));
	}

	RecommendationDto inspect(MarketItem item, MerchLensConfig config, HistoricalSignal historicalSignal)
	{
		long now = System.currentTimeMillis() / 1000L;
		if (item.getLatestPrice().getHigh() == null || item.getLatestPrice().getLow() == null)
		{
			return null;
		}

		String name = item.getMetadata().getName();
		int buyPrice = item.getLatestPrice().getLow();
		int sellPrice = item.getLatestPrice().getHigh();
		int tax = GeTax.tax(sellPrice, name);
		int netMargin = GeTax.netMargin(buyPrice, sellPrice, name);
		double roi = buyPrice > 0 ? (double) netMargin / buyPrice : 0;
		int quantity = Math.max(1, item.getMetadata().getLimit());
		int expectedProfit = netMargin * quantity;
		int capital = buyPrice * quantity;
		Map<String, Double> confidence = confidence(item, config, now, netMargin, roi, quantity, capital);
		double confidenceScore = confidence.get("score");
		double fillProbability = confidence.get("fillProbability");
		int latestAgeMinutes = latestAgeMinutes(item, now);
		String strategy = strategy(item, netMargin, roi, confidence);
		String risk = risk(strategy, confidenceScore);
		String action = netMargin > 0 ? "Watch" : "Avoid";
		List<String> warnings = warnings(item, now, netMargin, roi, confidence, strategy);

		if (historicalSignal != null && !isHistoricallyActionable(historicalSignal))
		{
			warnings.add(historicalSignal.getWarning());
		}
		else if (netMargin > 0 && latestAgeMinutes <= ACTIONABLE_PRICE_AGE_MINUTES)
		{
			action = "Buy";
		}
		if (netMargin <= 0)
		{
			strategy = "Avoid/Trap Detection";
			risk = "ADVANCED";
		}

		double expectedHold = Math.max(0.5, STRATEGY_HOLD_WINDOW_HOURS * (1.2 - fillProbability * 0.4));
		double score = "Avoid".equals(action) ? 0 : confidenceScore * Math.max(expectedProfit, 0) * fillProbability;
		String explanation = explanation(item, action, strategy, netMargin, roi, quantity, confidence, warnings);

		return new RecommendationDto(
			item.getMetadata().getId(),
			name,
			action,
			strategy,
			risk,
			buyPrice,
			sellPrice,
			quantity,
			item.getMetadata().getLimit(),
			tax,
			netMargin,
			expectedProfit,
			roi,
			capital,
			expectedHold,
			expectedProfit / Math.max(expectedHold, 0.25),
			expectedProfit / (double) Math.max(capital, 1) / Math.max(expectedHold, 0.25),
			score,
			hourlyVolume(item),
			lowSideVolume(item),
			highSideVolume(item),
			latestAgeMinutes,
			marketState(historicalSignal),
			marketWarning(historicalSignal),
			explanation,
			warnings,
			confidence
		);
	}

	private RecommendationDto evaluateStaple(MarketItem item, MerchLensConfig config, long now, HistoricalSignal historicalSignal)
	{
		if (item.getLatestPrice().getHigh() == null || item.getLatestPrice().getLow() == null)
		{
			return null;
		}
		int hourlyVolume = hourlyVolume(item);
		if (hourlyVolume < 1_000 || lowSideVolume(item) < 200 || highSideVolume(item) < 200)
		{
			return null;
		}
		int latestAgeMinutes = latestAgeMinutes(item, now);
		if (latestAgeMinutes > MAX_STAPLE_PRICE_AGE_MINUTES)
		{
			return null;
		}

		String name = item.getMetadata().getName();
		int buyPrice = item.getLatestPrice().getLow();
		int sellPrice = item.getLatestPrice().getHigh();
		if (buyPrice <= 0)
		{
			return null;
		}
		int tax = GeTax.tax(sellPrice, name);
		int netMargin = GeTax.netMargin(buyPrice, sellPrice, name);
		double roi = buyPrice > 0 ? (double) netMargin / buyPrice : 0;
		int buyLimit = Math.max(1, item.getMetadata().getLimit());
		int expectedProfit = clampedInt((long) netMargin * buyLimit);
		int capital = clampedInt((long) buyPrice * buyLimit);
		Map<String, Double> confidence = confidence(item, config, now, netMargin, roi, buyLimit, capital);
		boolean historicallyActionable = historicalSignal == null || isHistoricallyActionable(historicalSignal);
		String action = netMargin > 0 && latestAgeMinutes <= ACTIONABLE_PRICE_AGE_MINUTES && historicallyActionable ? "Buy" : "Watch";
		String explanation = netMargin > 0
			? "High-volume staple with a current post-tax spread. Still verify the live GE margin before committing."
			: "High-volume staple worth watching, but the current post-tax spread is not positive.";
		if (latestAgeMinutes > ACTIONABLE_PRICE_AGE_MINUTES)
		{
			explanation = "High-volume staple, but the latest Wiki buy/sell prices are stale. Refresh or manually margin-check before trading.";
		}
		if (historicalSignal != null && !historicallyActionable)
		{
			explanation = historicalSignal.getWarning();
		}

		return new RecommendationDto(
			item.getMetadata().getId(),
			name,
			action,
			"High Volume Staple",
			"SAFE",
			buyPrice,
			sellPrice,
			buyLimit,
			item.getMetadata().getLimit(),
			tax,
			netMargin,
			expectedProfit,
			roi,
			capital,
			Math.max(0.5, STRATEGY_HOLD_WINDOW_HOURS * 0.75),
			expectedProfit / Math.max(STRATEGY_HOLD_WINDOW_HOURS * 0.75, 0.25),
			expectedProfit / (double) Math.max(capital, 1) / Math.max(STRATEGY_HOLD_WINDOW_HOURS * 0.75, 0.25),
			confidence.get("score"),
			hourlyVolume,
			lowSideVolume(item),
			highSideVolume(item),
			latestAgeMinutes,
			marketState(historicalSignal),
			marketWarning(historicalSignal),
			explanation,
			warnings(item, now, netMargin, roi, confidence, "High Volume Staple"),
			confidence
		);
	}

	private RecommendationDto evaluateScreener(MarketItem item, MerchLensConfig config, long now, HistoricalSignal historicalSignal)
	{
		if (item.getLatestPrice().getHigh() == null || item.getLatestPrice().getLow() == null)
		{
			return null;
		}

		String name = item.getMetadata().getName();
		int buyPrice = item.getLatestPrice().getLow();
		int sellPrice = item.getLatestPrice().getHigh();
		if (buyPrice <= 0)
		{
			return null;
		}

		int buyLimit = Math.max(1, item.getMetadata().getLimit());
		int tax = GeTax.tax(sellPrice, name);
		int netMargin = GeTax.netMargin(buyPrice, sellPrice, name);
		double roi = buyPrice > 0 ? (double) netMargin / buyPrice : 0;
		int expectedProfit = clampedInt((long) netMargin * buyLimit);
		int capital = clampedInt((long) buyPrice * buyLimit);
		Map<String, Double> confidence = confidence(item, config, now, netMargin, roi, buyLimit, capital);
		int latestAgeMinutes = latestAgeMinutes(item, now);
		boolean historicallyActionable = historicalSignal == null || isHistoricallyActionable(historicalSignal);
		String action = netMargin > 0 && latestAgeMinutes <= ACTIONABLE_PRICE_AGE_MINUTES && historicallyActionable ? "Buy" : "Watch";
		if (netMargin <= 0)
		{
			action = "Avoid";
		}
		double expectedHold = Math.max(0.5, STRATEGY_HOLD_WINDOW_HOURS * 0.75);
		double score = Math.max(0, expectedProfit) * Math.max(0.01, confidence.get("score"));
		List<String> warnings = warnings(item, now, netMargin, roi, confidence, "Market Screener");
		if (historicalSignal != null && !historicallyActionable)
		{
			warnings.add(historicalSignal.getWarning());
		}

		return new RecommendationDto(
			item.getMetadata().getId(),
			name,
			action,
			"Market Screener",
			netMargin > 0 ? "BALANCED" : "ADVANCED",
			buyPrice,
			sellPrice,
			buyLimit,
			buyLimit,
			tax,
			netMargin,
			expectedProfit,
			roi,
			capital,
			expectedHold,
			expectedProfit / Math.max(expectedHold, 0.25),
			expectedProfit / (double) Math.max(capital, 1) / Math.max(expectedHold, 0.25),
			score,
			hourlyVolume(item),
			lowSideVolume(item),
			highSideVolume(item),
			latestAgeMinutes,
			marketState(historicalSignal),
			marketWarning(historicalSignal),
			"Market screener item. Review the card metrics and verify the live GE margin before trading.",
			warnings,
			confidence
		);
	}

	private Map<String, Double> confidence(MarketItem item, MerchLensConfig config, long now, int margin, double roi, int quantity, int capital)
	{
		double spreadQuality = margin <= 0 ? 0 : Math.min(1, (margin / Math.max(config.minimumProfit() / 20.0, 1)) * 0.45 + (roi / Math.max(STRATEGY_MINIMUM_ROI * 3, 0.0001)) * 0.55);
		double liquidity = liquidity(item, quantity);
		double stability = stability(item);
		double rangeReliability = rangeReliability(item);
		double freshness = freshness(item, now);
		double buyLimitFit = quantity <= 0 ? 0 : Math.min(1, 0.45 + (quantity / (double) item.getMetadata().getLimit()));
		double fillProbability = Math.min(1, liquidity * 0.4 + stability * 0.25 + freshness * 0.2 + rangeReliability * 0.15);
		double score = geometricMean(spreadQuality, liquidity, stability, rangeReliability, freshness, buyLimitFit, fillProbability);

		Map<String, Double> result = new LinkedHashMap<>();
		result.put("spreadQuality", spreadQuality);
		result.put("liquidity", liquidity);
		result.put("stability", stability);
		result.put("rangeReliability", rangeReliability);
		result.put("freshness", freshness);
		result.put("buyLimitFit", buyLimitFit);
		result.put("fillProbability", fillProbability);
		result.put("userFit", 1.0);
		result.put("score", score);
		return result;
	}

	private double liquidity(MarketItem item, int quantity)
	{
		int hourlyVolume = hourlyVolume(item);
		if (hourlyVolume <= 0)
		{
			return 0;
		}
		double relativeFill = Math.min(1, (hourlyVolume / (double) Math.max(quantity, 1)) / 8);
		double absoluteVolume = Math.min(1, hourlyVolume / 2_000.0);
		double sideBalance = sideBalance(item);
		return relativeFill * 0.45 + absoluteVolume * 0.35 + sideBalance * 0.20;
	}

	private double stability(MarketItem item)
	{
		if (item.getOneHour() == null || item.getOneHour().getAvgHighPrice() == null || item.getOneHour().getAvgLowPrice() == null)
		{
			return 0.45;
		}
		int liveSpread = Math.max(1, item.getLatestPrice().getHigh() - item.getLatestPrice().getLow());
		int hourlySpread = Math.max(1, item.getOneHour().getAvgHighPrice() - item.getOneHour().getAvgLowPrice());
		double expansion = Math.abs(liveSpread - hourlySpread) / (double) Math.max(hourlySpread, 1);
		return Math.max(0.1, Math.min(1, 1 - expansion / 2));
	}

	private double rangeReliability(MarketItem item)
	{
		if (item.getOneHour() == null || item.getOneHour().getAvgHighPrice() == null || item.getOneHour().getAvgLowPrice() == null)
		{
			return 0.35;
		}
		int currentMid = (item.getLatestPrice().getHigh() + item.getLatestPrice().getLow()) / 2;
		int hourlyMid = (item.getOneHour().getAvgHighPrice() + item.getOneHour().getAvgLowPrice()) / 2;
		double deviation = Math.abs(currentMid - hourlyMid) / (double) Math.max(hourlyMid, 1);
		return Math.max(0.2, Math.min(0.9, 1 - deviation / 0.08));
	}

	private double freshness(MarketItem item, long now)
	{
		Long highTime = item.getLatestPrice().getHighTime();
		Long lowTime = item.getLatestPrice().getLowTime();
		if (highTime == null || lowTime == null)
		{
			return 0;
		}
		double ageMinutes = (now - Math.min(highTime, lowTime)) / 60.0;
		if (ageMinutes <= 10)
		{
			return 1;
		}
		if (ageMinutes >= 120)
		{
			return 0.1;
		}
		return 1 - ((ageMinutes - 10) / 125);
	}

	private String strategy(MarketItem item, int margin, double roi, Map<String, Double> confidence)
	{
		int hourlyVolume = hourlyVolume(item);
		if (margin <= 0)
		{
			return "Avoid/Trap Detection";
		}
		if (hourlyVolume >= SAFE_MIN_HOURLY_VOLUME && confidence.get("rangeReliability") >= 0.7 && confidence.get("stability") >= 0.6)
		{
			return "Range-Bound Swing Flip";
		}
		if (roi >= 0.035 && hourlyVolume < item.getMetadata().getLimit() * 3)
		{
			return "High-Margin Gear Flip";
		}
		if (confidence.get("rangeReliability") >= 0.55 && confidence.get("stability") < 0.55)
		{
			return "Dip Recovery Flip";
		}
		return "Safe Passive Volume Flip";
	}

	private String risk(String strategy, double score)
	{
		if ("High-Margin Gear Flip".equals(strategy) || "Dip Recovery Flip".equals(strategy))
		{
			return score < 0.72 ? "ADVANCED" : "BALANCED";
		}
		return score >= 0.78 ? "SAFE" : "BALANCED";
	}

	private List<String> warnings(MarketItem item, long now, int margin, double roi, Map<String, Double> confidence, String strategy)
	{
		List<String> warnings = new ArrayList<>();
		if (margin <= 0)
		{
			warnings.add("Tax-negative or zero post-tax margin.");
		}
		if (confidence.get("freshness") < 0.45)
		{
			warnings.add("Price data is stale enough to be risky.");
		}
		if (latestAgeMinutes(item, now) > ACTIONABLE_PRICE_AGE_MINUTES)
		{
			warnings.add("Prices are stale; do not treat this as an immediate buy.");
		}
		if (confidence.get("liquidity") < 0.35)
		{
			warnings.add("Low volume may prevent one or both legs from filling.");
		}
		if (confidence.get("stability") < 0.35)
		{
			warnings.add("Recent price movement is too volatile for passive holding.");
		}
		if ("High-Margin Gear Flip".equals(strategy))
		{
			warnings.add("High-margin gear flips require more item knowledge and patience.");
		}
		if (roi < 0.0025)
		{
			warnings.add("ROI is thin after GE tax.");
		}
		return warnings;
	}

	private String explanation(MarketItem item, String action, String strategy, int margin, double roi, int quantity, Map<String, Double> confidence, List<String> warnings)
	{
		if ("Avoid".equals(action))
		{
			return "Avoid " + item.getMetadata().getName() + ": " + (warnings.isEmpty() ? "The evidence is not strong enough." : warnings.get(0));
		}
		int hourlyVolume = hourlyVolume(item);
		double coverage = hourlyVolume / (double) Math.max(quantity, 1);
		return action + " " + item.getMetadata().getName() + ": " + strategy + " with " + String.format("%,d", margin)
			+ " GP net margin (" + String.format("%.2f%%", roi * 100) + " ROI). Confidence is "
			+ String.format("%.0f%%", confidence.get("score") * 100) + " because 1h volume covers "
			+ String.format("%.1f", coverage) + "x the quantity, the spread survives 2% GE tax, and prices are fresh.";
	}

	private double geometricMean(double... values)
	{
		double product = 1;
		for (double value : values)
		{
			product *= Math.max(0, Math.min(1, value));
		}
		return Math.pow(product, 1.0 / values.length);
	}

	private int clampedInt(long value)
	{
		if (value > Integer.MAX_VALUE)
		{
			return Integer.MAX_VALUE;
		}
		if (value < Integer.MIN_VALUE)
		{
			return Integer.MIN_VALUE;
		}
		return (int) value;
	}

	private int hourlyVolume(MarketItem item)
	{
		int hourlyVolume = item.getOneHour() == null ? 0 : item.getOneHour().getTotalVolume();
		if (hourlyVolume <= 0 && item.getFiveMinute() != null)
		{
			hourlyVolume = item.getFiveMinute().getTotalVolume() * 12;
		}
		return hourlyVolume;
	}

	private int latestAgeMinutes(MarketItem item, long now)
	{
		Long highTime = item.getLatestPrice().getHighTime();
		Long lowTime = item.getLatestPrice().getLowTime();
		if (highTime == null || lowTime == null)
		{
			return Integer.MAX_VALUE;
		}
		return (int) Math.max(0, (now - Math.min(highTime, lowTime)) / 60);
	}

	private boolean isHighVolumeStaple(MarketItem item)
	{
		return HighVolumeItemCatalog.isCandidate(item.getMetadata().getName());
	}

	private int lowSideVolume(MarketItem item)
	{
		if (item.getOneHour() != null)
		{
			return item.getOneHour().getLowPriceVolume();
		}
		return item.getFiveMinute() == null ? 0 : item.getFiveMinute().getLowPriceVolume() * 12;
	}

	private int highSideVolume(MarketItem item)
	{
		if (item.getOneHour() != null)
		{
			return item.getOneHour().getHighPriceVolume();
		}
		return item.getFiveMinute() == null ? 0 : item.getFiveMinute().getHighPriceVolume() * 12;
	}

	private double sideBalance(MarketItem item)
	{
		int lowSide = lowSideVolume(item);
		int highSide = highSideVolume(item);
		int weakerSide = Math.min(lowSide, highSide);
		int strongerSide = Math.max(lowSide, highSide);
		if (strongerSide <= 0)
		{
			return 0;
		}
		return weakerSide / (double) strongerSide;
	}

	private boolean isHistoricallyActionable(HistoricalSignal signal)
	{
		return signal.getMarketState() == HistoricalSignal.MarketState.STABLE
			|| signal.getMarketState() == HistoricalSignal.MarketState.RANGE_BOUND;
	}

	private String marketState(HistoricalSignal signal)
	{
		return signal == null ? "UNKNOWN" : signal.getMarketState().name();
	}

	private String marketWarning(HistoricalSignal signal)
	{
		return signal == null ? "" : signal.getWarning();
	}
}

package com.merchlens;

import net.runelite.api.GrandExchangeOffer;

class TrackedOffer
{
	private int slot;
	private int itemId;
	private long price;
	private int totalQuantity;
	private int filledQuantity;
	private long spent;
	private String state;
	private long firstSeenAt;
	private long lastUpdatedAt;
	private boolean trackedStartKnown;

	TrackedOffer()
	{
	}

	TrackedOffer(int slot, GrandExchangeOffer offer, long now, boolean trackedStartKnown)
	{
		this.slot = slot;
		this.firstSeenAt = now;
		this.trackedStartKnown = trackedStartKnown;
		update(offer, now);
	}

	int getSlot()
	{
		return slot;
	}

	int getItemId()
	{
		return itemId;
	}

	long getPrice()
	{
		return price;
	}

	int getTotalQuantity()
	{
		return totalQuantity;
	}

	int getFilledQuantity()
	{
		return filledQuantity;
	}

	long getSpent()
	{
		return spent;
	}

	String getState()
	{
		return state;
	}

	long getFirstSeenAt()
	{
		return firstSeenAt;
	}

	long getLastUpdatedAt()
	{
		return lastUpdatedAt;
	}

	boolean isTrackedStartKnown()
	{
		return trackedStartKnown;
	}

	boolean isBuyOffer()
	{
		return isBuyState(state);
	}

	String offerKey()
	{
		return slot + ":" + firstSeenAt + ":" + itemId + ":" + price + ":" + totalQuantity + ":" + (isBuyOffer() ? "BUY" : "SELL");
	}

	boolean isVisible()
	{
		return itemId > 0 && totalQuantity > 0 && state != null && !"EMPTY".equals(state);
	}

	boolean matches(GrandExchangeOffer offer)
	{
		if (offer == null || offer.getState() == null)
		{
			return false;
		}
		return itemId == offer.getItemId()
			&& price == offer.getPrice()
			&& totalQuantity == offer.getTotalQuantity()
			&& offer.getQuantitySold() >= filledQuantity
			&& offer.getSpent() >= spent
			&& sameSide(state, offer.getState().name());
	}

	void update(GrandExchangeOffer offer, long now)
	{
		itemId = offer.getItemId();
		price = offer.getPrice();
		totalQuantity = offer.getTotalQuantity();
		filledQuantity = offer.getQuantitySold();
		spent = offer.getSpent();
		state = offer.getState().name();
		lastUpdatedAt = now;
	}

	private boolean sameSide(String left, String right)
	{
		if (left == null || right == null)
		{
			return false;
		}
		return isBuyState(left) == isBuyState(right) && isSellState(left) == isSellState(right);
	}

	private boolean isBuyState(String value)
	{
		return value.contains("BUY") || "BOUGHT".equals(value);
	}

	private boolean isSellState(String value)
	{
		return value.contains("SELL") || "SOLD".equals(value);
	}
}

