	private Color trendStatusColor(RecommendationDto rec)
	{
		if (rec.getMarketState() == null || "UNKNOWN".equals(rec.getMarketState()))
		{
			return Color.LIGHT_GRAY;
		}
		return trendColor(rec.getMarketState());
