package com.merchlens;

import com.google.gson.Gson;
import java.util.List;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Assert;
import org.junit.Test;

public class OfferTrackerTest
{
	@Test
	public void startupOfferWithoutSavedStateShowsUnknownTime()
	{
		OfferTracker tracker = new OfferTracker(null, new Gson());

		tracker.record(3, offer(GrandExchangeOfferState.BUYING, 4151, 1_000_000, 8, 2, 2_000_000));

		List<TrackedOffer> offers = tracker.activeOffers();
		Assert.assertEquals(1, offers.size());
		Assert.assertEquals(3, offers.get(0).getSlot());
		Assert.assertFalse(offers.get(0).isTrackedStartKnown());
		Assert.assertEquals(2, offers.get(0).getFilledQuantity());
		Assert.assertEquals(8, offers.get(0).getTotalQuantity());
	}

	@Test
	public void matchingSlotUpdatePreservesOriginalTrackedStart()
	{
		OfferTracker tracker = new OfferTracker(null, new Gson());

		tracker.record(1, offer(GrandExchangeOfferState.SELLING, 385, 100, 100, 10, 1_000));
		TrackedOffer first = tracker.activeOffers().get(0);
		long firstSeenAt = first.getFirstSeenAt();

		tracker.record(1, offer(GrandExchangeOfferState.SELLING, 385, 100, 100, 70, 7_000));
		TrackedOffer updated = tracker.activeOffers().get(0);

		Assert.assertEquals(firstSeenAt, updated.getFirstSeenAt());
		Assert.assertEquals(70, updated.getFilledQuantity());
		Assert.assertEquals(7_000L, updated.getSpent());
	}

	@Test
	public void matchingOfferAllowsProgressButRejectsRegressions()
	{
		TrackedOffer tracked = new TrackedOffer(
			2,
			offer(GrandExchangeOfferState.BUYING, 11840, 1_000_000, 10, 3, 3_000_000),
			100,
			true
		);

		Assert.assertTrue(tracked.matches(offer(GrandExchangeOfferState.BUYING, 11840, 1_000_000, 10, 7, 7_000_000)));
		Assert.assertFalse(tracked.matches(offer(GrandExchangeOfferState.BUYING, 11840, 1_000_000, 10, 0, 0)));
		Assert.assertFalse(tracked.matches(offer(GrandExchangeOfferState.BUYING, 11840, 1_000_000, 10, 7, 2_000_000)));
	}

	@Test
	public void trackedPendingBuyEmitsActualFillValueWhenObservedCompleted()
	{
		OfferTracker tracker = new OfferTracker(null, new Gson());
		tracker.record(1, offer(GrandExchangeOfferState.BUYING, 560, 100, 5_000, 0, 0));

		OfferFill fill = tracker.record(1, offer(GrandExchangeOfferState.BOUGHT, 560, 100, 5_000, 1_200, 117_600));

		Assert.assertNotNull(fill);
		Assert.assertEquals(OfferFill.Side.BUY, fill.getSide());
		Assert.assertEquals(1_200, fill.getQuantity());
		Assert.assertEquals(117_600, fill.getTotalValue());
	}

	@Test
	public void tracksOfferValuesBeyondTheLegacyIntegerLimit()
	{
		OfferTracker tracker = new OfferTracker(null, new Gson());
		tracker.record(1, offer(GrandExchangeOfferState.BUYING, 560, 3_000_000_000L, 2, 0, 0));

		OfferFill fill = tracker.record(1, offer(GrandExchangeOfferState.BOUGHT, 560, 3_000_000_000L, 2, 1, 3_000_000_000L));

		Assert.assertNotNull(fill);
		Assert.assertEquals(3_000_000_000L, tracker.activeOffers().get(0).getPrice());
		Assert.assertEquals(3_000_000_000L, tracker.activeOffers().get(0).getSpent());
		Assert.assertEquals(3_000_000_000L, fill.getTotalValue());
	}

	private GrandExchangeOffer offer(GrandExchangeOfferState state, int itemId, long price, int totalQuantity, int filledQuantity, long spent)
	{
		return new StubOffer(state, itemId, price, totalQuantity, filledQuantity, spent);
	}

	private static class StubOffer implements GrandExchangeOffer
	{
		private final GrandExchangeOfferState state;
		private final int itemId;
		private final long price;
		private final int totalQuantity;
		private final int filledQuantity;
		private final long spent;

		StubOffer(GrandExchangeOfferState state, int itemId, long price, int totalQuantity, int filledQuantity, long spent)
		{
			this.state = state;
			this.itemId = itemId;
			this.price = price;
			this.totalQuantity = totalQuantity;
			this.filledQuantity = filledQuantity;
			this.spent = spent;
		}

		@Override
		public int getQuantitySold()
		{
			return filledQuantity;
		}

		@Override
		public int getItemId()
		{
			return itemId;
		}

		@Override
		public int getTotalQuantity()
		{
			return totalQuantity;
		}

		@Override
		public long getPrice()
		{
			return price;
		}

		@Override
		public long getSpent()
		{
			return spent;
		}

		@Override
		public GrandExchangeOfferState getState()
		{
			return state;
		}
	}
}

package com.merchlens;

import com.merchlens.model.ItemMetadata;
import com.merchlens.model.LatestPrice;
import com.merchlens.model.MarketItem;
import com.merchlens.model.PriceWindow;
import com.merchlens.model.RecommendationDto;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Assert;
import org.junit.Test;

public class RecommendationEngineTest
{
	private final RecommendationEngine engine = new RecommendationEngine();

	@Test
	public void taxNegativeItemIsAvoided() throws Exception
	{
		RecommendationDto recommendation = engine.inspect(item("Coal", 1020, 1000, 10_000, 100_000), config(), null);

		Assert.assertEquals("Avoid", recommendation.getAction());
		Assert.assertTrue(recommendation.getNetMargin() <= 0);
	}

	@Test
	public void highVolumeProfitableItemGetsBuyRecommendation() throws Exception
	{
		RecommendationDto recommendation = engine.highVolumeStaples(
			Collections.singletonList(item("Coal", 1300, 1000, 10_000, 100_000)),
			config()
		).get(0);

		Assert.assertEquals("Buy", recommendation.getAction());
		Assert.assertTrue(recommendation.getExpectedProfit() > 0);
		Assert.assertTrue(recommendation.getConfidence().get("liquidity") > 0.5);
	}

	@Test
	public void veryLowVolumeItemIsNotRecommended() throws Exception
	{
		List<RecommendationDto> recommendations = engine.highVolumeStaples(
			Collections.singletonList(item("Coal", 10_000_000, 5_000_000, 10_000, 1)),
			config()
		);

		Assert.assertTrue(recommendations.isEmpty());
	}

	@Test
	public void oneSidedVolumeItemIsNotRecommended() throws Exception
	{
		List<RecommendationDto> recommendations = engine.highVolumeStaples(
			Collections.singletonList(item("Coal", 10_000_000, 5_000_000, 10_000, 2_000, 2_000, 0)),
			config()
		);

		Assert.assertTrue(recommendations.isEmpty());
	}

	@Test
	public void screenerKeepsLowVolumeItemsForUiFilters() throws Exception
	{
		List<RecommendationDto> recommendations = engine.screener(
			Collections.singletonList(item(1300, 1000, 10_000, 1)),
			config()
		);

		Assert.assertEquals(1, recommendations.size());
		Assert.assertTrue(recommendations.get(0).getNetMargin() > 0);
	}

	@Test
	public void screenerDoesNotApplyMinimumProfitFloor() throws Exception
	{
		RecommendationDto recommendation = engine.screener(
			Collections.singletonList(item(1030, 1000, 1, 1)),
			config()
		).get(0);

		Assert.assertTrue(recommendation.getNetMargin() > 0);
		Assert.assertTrue(recommendation.getExpectedProfit() < config().minimumProfit());
	}

	@Test
	public void flowProfitCapsFullLimitProfitAtObservedWeakerSideVolume() throws Exception
	{
		RecommendationDto recommendation = engine.screener(
			Collections.singletonList(item("Arceuus library teleport (tablet)", 3328, 2745, 10_000, 219, 215, 4)),
			config()
		).get(0);

		Assert.assertEquals(16, recommendation.getFourHourFlowQuantity());
		Assert.assertEquals(8_272L, recommendation.getFourHourFlowProfit());
		Assert.assertTrue(recommendation.isSeverelyFlowLimited());
		Assert.assertEquals(5_170_000, recommendation.getExpectedProfit());
	}

	@Test
	public void screenerRanksObservedFlowAheadOfIlliquidFullLimitProfit() throws Exception
	{
		List<RecommendationDto> recommendations = engine.screener(
			Arrays.asList(
				item("Thin tablet", 3328, 2745, 10_000, 219, 215, 4),
				item("Liquid supply", 1300, 1000, 1000, 2000, 1000, 1000)
			),
			config()
		);

		Assert.assertEquals("Liquid supply", recommendations.get(0).getItemName());
		Assert.assertTrue(recommendations.get(0).getFourHourFlowProfit() > recommendations.get(1).getFourHourFlowProfit());
		Assert.assertTrue(recommendations.get(1).getExpectedProfit() > recommendations.get(0).getExpectedProfit());
	}

	@Test
	public void highVolumeStaplesUsesExpandedResearchCatalog() throws Exception
	{
		List<RecommendationDto> recommendations = engine.highVolumeStaples(
			Arrays.asList(
				item("Coal", 170, 150, 13_000, 8_000),
				item("Games necklace(8)", 1_000, 950, 10_000, 8_000)
			),
			config()
		);

		List<String> itemNames = recommendations.stream()
			.map(RecommendationDto::getItemName)
			.collect(Collectors.toList());
		Assert.assertTrue(itemNames.contains("Coal"));
		Assert.assertTrue(itemNames.contains("Games necklace(8)"));
	}

	@Test
	public void highVolumeStaplesExcludesGenericGearNotInCatalog() throws Exception
	{
		List<RecommendationDto> recommendations = engine.highVolumeStaples(
			Collections.singletonList(item("Abyssal whip", 1_600_000, 1_500_000, 70, 8_000)),
			config()
		);

		Assert.assertTrue(recommendations.isEmpty());
	}

	@Test
	public void expensiveHighVolumeItemIsNotSilentlyExcludedByCashStack() throws Exception
	{
		List<RecommendationDto> recommendations = engine.highVolumeStaples(
			Collections.singletonList(item("Coal", 75_000_000, 60_000_000, 8, 100_000)),
			config()
		);

		Assert.assertEquals(1, recommendations.size());
	}

	@Test
	public void highVolumeStaplesKeepFullBuyLimitForDisplay() throws Exception
	{
		RecommendationDto recommendation = engine.highVolumeStaples(
			Collections.singletonList(item("Coal", 1300, 1000, 100_000, 300_000)),
			config()
		).get(0);

		Assert.assertEquals(100_000, recommendation.getBuyLimit());
		Assert.assertEquals(GeTax.netMargin(1000, 1300, "Coal") * 100_000, recommendation.getExpectedProfit());
	}

	private MerchLensConfig config()
	{
		return new MerchLensConfig()
		{
			@Override
			public int minimumProfit()
			{
				return 10_000;
			}
		};
	}

	private MarketItem item(int high, int low, int limit, int hourlyVolume) throws Exception
	{
		return item("Test item", high, low, limit, hourlyVolume, hourlyVolume / 2, hourlyVolume / 2);
	}

	private MarketItem item(String name, int high, int low, int limit, int hourlyVolume) throws Exception
	{
		return item(name, high, low, limit, hourlyVolume, hourlyVolume / 2, hourlyVolume / 2);
	}

	private MarketItem item(String name, int high, int low, int limit, int hourlyVolume, int highVolume, int lowVolume) throws Exception
	{
		ItemMetadata metadata = new ItemMetadata();
		set(metadata, "id", Math.abs(name.hashCode()));
		set(metadata, "name", name);
		set(metadata, "members", true);
		set(metadata, "limit", limit);

		LatestPrice latest = new LatestPrice();
		long now = System.currentTimeMillis() / 1000L;
		set(latest, "high", high);
		set(latest, "low", low);
		set(latest, "highTime", now - 60);
		set(latest, "lowTime", now - 60);

		PriceWindow oneHour = new PriceWindow();
		set(oneHour, "avgHighPrice", high);
		set(oneHour, "avgLowPrice", low);
		set(oneHour, "highPriceVolume", highVolume);
		set(oneHour, "lowPriceVolume", lowVolume);

		PriceWindow fiveMinute = new PriceWindow();
		set(fiveMinute, "avgHighPrice", high);
		set(fiveMinute, "avgLowPrice", low);
		set(fiveMinute, "highPriceVolume", hourlyVolume / 24);
		set(fiveMinute, "lowPriceVolume", hourlyVolume / 24);

		return new MarketItem(metadata, latest, fiveMinute, oneHour);
	}

	private void set(Object target, String fieldName, Object value) throws Exception
	{
		Field field = target.getClass().getDeclaredField(fieldName);
		field.setAccessible(true);
		field.set(target, value);
	}
}
